        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("")

    def test_rejects_non_string_title(self, svc):
        with pytest.raises(ValueError, match="must be a string"):
            svc.create(123)  # type: ignore

    def test_rejects_too_long_title(self, svc):
        with pytest.raises(ValueError, match="50 characters"):
            svc.create("x" * 51)

    def test_rejects_invalid_priority(self, svc, mock_repo):
        mock_repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="priority must be"):
            svc.create("task", priority="bad")  # type: ignore

    def test_rejects_naive_due_at(self, svc, mock_repo):
        mock_repo.next_id.return_value = 1
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("task", due_at=datetime(2025, 1, 1))

