        mock_repo.get.return_value = make_task(id=1, tags=[Tag("bug"), Tag("feature")])
        task = svc.remove_tag(1, "bug")
        assert all(t.name != "bug" for t in task.tags)

    def test_remove_missing_tag_raises(self, svc, mock_repo):
        mock_repo.get.return_value = make_task(id=1, tags=[])
        with pytest.raises(ValueError, match="not attached"):
